-- Gathering is an independent purpose. Published policies and earlier decisions
-- are unchanged; neither storage nor existing AI permission implies this grant.
ALTER TABLE policy_versions DROP CONSTRAINT policy_versions_kind_check;
ALTER TABLE policy_versions ADD CONSTRAINT policy_versions_kind_check CHECK(kind IN ('privacy_notice','private_story_storage','ai_text_processing','private_photo_storage','private_person_photo_storage','virtual_gift_storage','person_gift_returns','gift_delivery_photo_storage','private_letter_storage','person_letter_replies','person_gather_replies'));
ALTER TABLE consent_events DROP CONSTRAINT consent_events_purpose_check;
ALTER TABLE consent_events ADD CONSTRAINT consent_events_purpose_check CHECK(purpose IN ('privacy_notice','private_story_storage','ai_text_processing','private_photo_storage','private_person_photo_storage','virtual_gift_storage','person_gift_returns','gift_delivery_photo_storage','private_letter_storage','person_letter_replies','person_gather_replies'));
ALTER TABLE consent_events DROP CONSTRAINT consent_events_check;
ALTER TABLE consent_events ADD CONSTRAINT consent_events_check CHECK((purpose='privacy_notice' AND decision='acknowledge') OR (purpose IN ('private_story_storage','ai_text_processing','private_photo_storage','private_person_photo_storage','virtual_gift_storage','person_gift_returns','gift_delivery_photo_storage','private_letter_storage','person_letter_replies','person_gather_replies') AND decision IN ('grant','revoke')));
ALTER TABLE consent_events DROP CONSTRAINT consent_events_ai_notice_binding;
ALTER TABLE consent_events ADD CONSTRAINT consent_events_ai_notice_binding CHECK(CASE
 WHEN purpose IN ('ai_text_processing','private_photo_storage','private_person_photo_storage','virtual_gift_storage','person_gift_returns','gift_delivery_photo_storage','private_letter_storage','person_letter_replies','person_gather_replies') AND decision='grant' THEN notice_authorization_version IS NOT NULL AND notice_authorization_version>0
 WHEN purpose='private_story_storage' AND decision='grant' THEN notice_authorization_version IS NULL OR notice_authorization_version>0
 ELSE notice_authorization_version IS NULL END);

INSERT INTO policy_versions(id,kind,version,document_zh_cn,document_en) VALUES
('763fa34c-7747-4890-b764-59992b35bb24','person_gather_replies',1,
'西界 AI 围坐回应授权（OpenAI 联调）

这是同一账号内虚构人物文字围坐的独立 AI 用途，不扩大已有文字、照片、书信、赠礼或 AI 文字处理授权。新发言须同时具有私人文字保存权限和本授权；本授权不会自动授予旧 AI 文字处理或任何其他用途。
允许后，你此后主动提交的每条围坐文字，可由受理时同世界的两至三位有效人物各回应一轮，最多三位。每轮名单固定，重试不换人补位，也不会启动自动轮聊。西界可将本轮用户文字、当前发言人的必要文字画像、当前虚拟世界和最近已提交的迁居、该人物实际参加过的旧围坐共享文字发送至 OpenAI API，生成明确标识为 AI 的人物回应。旧围坐只取本轮之前最多二十条相关文字，不把本轮其他人物刚生成的文本继续交给下一位。
若受理时你还允许独立的 AI 文字处理，本轮人物可以另外使用自己当前获准的珍藏和私聊自动长期记忆，它们可能在本账号的共享围坐回应中提及。每位人物只取得自己的这些私人记忆，不向其他人物提供原始私聊或私人记忆原文；旧围坐共享回复涉及的他人记忆只验证来源是否仍然有效，不读取其记忆正文。未允许旧 AI 文字处理时，不读取珍藏或私聊长期记忆，仍可依据必要人物资料、虚拟世界及自己参加过的围坐回应。后来允许旧 AI 不会为已受理轮次补加记忆。
本授权仅包含文字，不读取原始私聊、书信、照片、音视频，不自动学习围坐、自动珍藏、生成世界剧情或推送，不执行迁居、赠礼、支付、发放资产或跨账号通信。共享历史中的 AI 表达只是对话语境，不能当作真实用户经历；虚拟世界和迁居不是真实人物生平，模型不代表真实本人的意识、承诺或行为。
每位人物最多保存一条本轮真实回复；暂时故障可有限重试，最多三次业务尝试，失败不用模板补成功，不承诺外部模型请求恰好调用一次。请求使用 store:false，保存必要的模型、响应标识、提示版本和实际使用的来源引用，不保存模型密钥。资料、人物资格和所捕获的精确账号、存储、围坐及适用的旧 AI 授权版本，在模型前后和写回前复核。已经发送给提供方的内容不能靠撤回收回。
你可以单独撤回本授权，停止新的处理、剩余任务及迟到写回，不删除已保存的围坐历史；已有内容仍按私人文字保存权限读取。相关授权撤回再允许、人物迁出再迁回都不会恢复旧任务，已成功回复不会重复生成。源消息删除、人物失去资格或账号注销同样阻止相应剩余任务。独立资料导出与账号注销不要求重新授予本用途，可导出或清理已存消息、名单、任务和必要来源记录。本授权仅用于名单内合成账号的非生产本机验证，不表示正式模型服务或生产发布。',
'Xijie AI gathering reply permission (OpenAI sandbox)

This independent AI purpose covers text gatherings among fictional characters within one account. It does not expand existing text, photo, letter, gift or AI text-processing permission. New messages require both private text storage and this permission. Granting this purpose does not grant the old AI text-processing purpose or any other permission.
After you allow it, each new gathering message you actively submit may receive one reply from each of two or three eligible characters in that world at acceptance, with a maximum of three characters. The roster is fixed for that round; retries do not replace participants or start automatic conversation loops. Xijie may send the current user message, the speaking character necessary text profile, current virtual world and recent committed moves, and shared text from earlier gathering rounds that character actually participated in to the OpenAI API for an explicitly AI-labelled reply. At most twenty relevant historical messages preceding the current round are used. Other characters newly generated replies in this same round are not passed to the next speaker.
If independent AI text processing is also allowed when the round is accepted, each speaker may additionally use their own currently authorized treasured originals and automatic long-term memories from private chats. These may be mentioned in the shared gathering reply within this account. Each character receives only their own private memory content, never another character raw private chats or private memory originals. References to another character memories in old shared gathering replies are validated without loading those private originals. Without the old AI text-processing permission, treasured and private-chat long-term memories are not read; necessary character text, virtual world and gatherings the character participated in may still support a reply. A later AI grant does not add memories to an already accepted round.
This purpose is text only. It excludes raw private-chat histories, letters, photos, audio, video, automatic learning from gatherings, automatic treasuring, world stories, push notifications, moves, gifts, payments, asset grants and communication across accounts. Historical AI expressions are conversational context, not factual user experiences. Virtual worlds and moves are not real biographies, and model output does not represent a real person consciousness, promises or actions.
Each character has at most one saved actual reply per round. Temporary failures may retry within three business attempts. Templates never replace a failed model result, and exactly-once external requests are not promised. Requests use store:false. Necessary model, response identifier, prompt version and actual source references are saved without model secrets. Character eligibility, source data and the captured exact account, storage, gathering and applicable old AI authorization versions are rechecked before and after generation and before commit. Withdrawal cannot recall content already sent to the provider.
You may independently withdraw this permission to stop new processing, remaining tasks and late writeback without deleting saved gathering history. Existing content remains readable under private text storage permission. Renewed permission or a character moving away and back does not revive old tasks, and successful replies are not generated again. Source-message deletion, loss of character eligibility or account erasure also prevents the corresponding remaining work. Independent data export and account erasure do not require renewed permission and can retrieve or remove stored messages, participants, tasks and necessary sources. This purpose is restricted to allowlisted synthetic accounts in non-production local verification, not a production model service or release.');
